				newAssignPage.getProperty(".pyAssignActions(<LAST>).pyActionInstructions").setValue(actionName);
				return true;
			}
			else
				return false;
		} catch (PRRuntimeException pre) {
			// shouldn't get here.
			oLog.error(pre.getMessage(), pre);
			return false;
		}

		return newParamsPage.getAsBoolean("AddOpRetVal");
	}

